  deleteSighting,
  getSighting,
  id,
  onCancel,
  onDeleted,
  onNotFoundReturn,
  onSaved,
}: Readonly<{
  correctSighting: CorrectSighting;
  deleteSighting: DeleteSighting;
  getSighting: GetSighting;
  id: number;
